rowdata.pyStepsJavaSource:
// If creating an output page when all goes well isn't desired then we must
// clear it at the start, because callers will use @OperationFail() afterwards
// and we wouldn't want an incorrect result because of a page from a previous op.
if (tools.getParamValue("OutputPageName").equals(""))
   tools.putParamValue("OutputPageName", "pyOutput");
ClipboardPage op = tools.findPage(tools.getParamValue("OutputPageName"));
if (op != null)
{
   op.getProperty("pyStatus").clearValue();
   op.getProperty("pyErrors").removeFromClipboard();
}

StringMap casetype = new HashStringMap();
casetype.putString("pxObjClass", "Rule-Obj-CaseType");
casetype.putString("pyClassName", myStepPage.getString("pxObjClass"));
casetype.putString("pyPurpose", "pyDefault");
ParameterPage pp = new ParameterPage();
pp.putString("pyCaseTypePurpose", "GETDEFAULTVALUESFROMFEDERATED");
pp.putString("PageListName", "FederatedSystemParams");
tools.doAction(casetype, null, pp);

ClipboardPage cpParams = tools.findPage("FederatedSystemParams");
if(cpParams != null)
{
	ClipboardProperty paramsList = cpParams.getProperty(".pxResults");
	if(paramsList != null)
	{
		java.util.Iterator itParamsList = paramsList.iterator();
		while (itParamsList.hasNext())
		{
			ClipboardPage paramPage = ((ClipboardProperty)itParamsList.next()).getPageValue();
			String paramName = paramPage.getString("pyTargetPropertyName");
                           String parameterName = paramName;
                   	if(paramName.startsWith("."))
                    		parameterName = paramName.substring(1);
			String paramValue = tools.getParamValue(com.pegarules.generated.pega_processengine_workutilities.pzPageNameClean(tools, parameterName));
			if(paramValue != null && !"".equals(paramValue))
				myStepPage.getProperty(paramName).setValue(paramValue);
		}
	}
cpParams.removeFromClipboard();
}
